<script lang="ts">
 import ConfirmDialog from './common/ConfirmDialog.svelte';
 import { confirmDialog } from './ui';
 import { saveConfig } from './api';
 export let profiles:any[]=[]; export let revision=0; export let language='en'; export let onSaved:()=>void=()=>{};
 const t=(zh:string,en:string)=>language==='zh-CN'?zh:en;
 let query='', active='all', sortKey='name', asc=true, selected:string[]=[], open=false, editing:any=null, draft:any={}, error='', importFile:HTMLInputElement, preview:any=null, bulkActive='', bulkLate='', bulkReturn='';
 const split=(s:string,comma=false)=>s.split(comma?/[,\n]/:/[\n]/).map(x=>x.trim()).filter(Boolean);
 function start(p:any=null){editing=p;draft=p?{...p,includedSubgroups:[...(p.includedSubgroups||[])].join('\n'),meetingIds:(p.meetingIds||[]).join('\n'),topicKeywords:(p.topicKeywords||[]).join(', '),groupSortOrder:(p.groupSortOrder||[]).join('\n')}:{id:`profile-${Date.now()}`,name:'',description:'',includedSubgroups:'*',lateAfterMinutes:10,returnWindowMinutes:8,meetingIds:'',topicKeywords:'',groupSortOrder:'',active:true};error='';open=true}
 async function put(rows:any[]){await saveConfig('profiles',rows);onSaved()}
 async function save(){const p={...draft,includedSubgroups:split(draft.includedSubgroups,true),meetingIds:split(draft.meetingIds,true),topicKeywords:split(draft.topicKeywords,true),groupSortOrder:split(draft.groupSortOrder,true)};delete p.specialParticipants;delete p.blacklist;if(!p.name.trim()){error=t('名称为必填项','Name is required');return}if(!Number.isInteger(+p.lateAfterMinutes)||+p.lateAfterMinutes<=0||!Number.isInteger(+p.returnWindowMinutes)||+p.returnWindowMinutes<=0){error=t('迟到和返回阈值必须为正整数','Late and return thresholds must be positive integers');return}try{await put(editing?profiles.map(x=>x.id===p.id?p:x):[...profiles,p]);open=false}catch(e:any){error=e.message}}
 async function remove(){const ids=selected.filter(id=>id!=='default-all');if(!ids.length)return;if(!await confirmDialog({title:t('确认删除','Confirm deletion'),message:t('删除所选配置？默认配置会保留。','Delete selected profiles? The default profile is kept.'),destructive:true}))return;try{await put(profiles.filter(p=>!ids.includes(p.id)));selected=[]}catch(e:any){error=e.message}}
 async function bulkEdit(){if(!selected.length)return;const rows=profiles.map(p=>{if(!selected.includes(p.id)||p.id==='default-all')return p;const n={...p};if(bulkActive!=='')n.active=bulkActive==='true';if(bulkLate.trim()&&Number.isInteger(Number(bulkLate))&&Number(bulkLate)>0)n.lateAfterMinutes=Number(bulkLate);if(bulkReturn.trim()&&Number.isInteger(Number(bulkReturn))&&Number(bulkReturn)>0)n.returnWindowMinutes=Number(bulkReturn);return n});try{await put(rows);bulkActive='';bulkLate='';bulkReturn=''}catch(e:any){error=e.message}}
 async function reset(){const p=profiles.find(x=>x.id==='default-all');if(!p||!await confirmDialog({title:t('恢复工厂默认值','Reset factory defaults'),message:t('将默认配置恢复为工厂设置（迟到 10 分钟、返回 8 分钟、启用、无分组）？','Reset default profile to factory settings (late 10, return 8, active, no subgroups)?'),destructive:true}))return;try{await put(profiles.map(x=>x.id==='default-all'?{...x,description:'Factory default profile',includedSubgroups:[],lateAfterMinutes:10,returnWindowMinutes:8,meetingIds:[],topicKeywords:[],groupSortOrder:[],active:true}:x))}catch(e:any){error=e.message}}
 function exportJson(ids:string[]=[]){const arr=profiles.filter(p=>!ids.length||ids.includes(p.id)).map(({specialParticipants,blacklist,...p})=>p);const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d+Z$/,'Z');const name=ids.length?`attendance-profiles-selected-${stamp}.json`:`attendance-profiles-${stamp}.json`;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(arr,null,2)],{type:'application/json'}));a.download=name;a.click();URL.revokeObjectURL(a.href)}
 async function readImport(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;try{const data=JSON.parse(await f.text());if(!Array.isArray(data))throw Error(t('JSON 必须是数组','JSON must be an array'));const r=await fetch('/api/profiles/import/preview',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({profiles:data})});preview=await r.json();if(!r.ok)throw Error(preview.message||'Preview failed')}catch(e:any){error=e.message}finally{(e.target as HTMLInputElement).value=''}}
 async function commit(){try{const r=await fetch('/api/profiles/import/commit',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(preview)});const d=await r.json();if(!r.ok)throw Error(d.message||'Import failed');preview=null;revision=d.revision;onSaved()}catch(e:any){error=e.message}}
 $: visible=profiles.filter(p=>(!query||`${p.name} ${p.description}`.toLowerCase().includes(query.toLowerCase()))&&(active==='all'||String(p.active)===active)).sort((a,b)=>String(a[sortKey]??'').localeCompare(String(b[sortKey]??''))*(asc?1:-1));
</script>
<section class="panel profile-workspace"><div class="panel-title"><div><h2>{t('考勤配置','Attendance profiles')}</h2><p>{t('配置会议匹配、小组范围和考勤阈值。','Configure meeting matching, subgroup scope, and attendance thresholds.')}</p></div><div class="actions"><button class="primary" onclick={()=>start()}>＋ {t('新增','Add')}</button><button onclick={()=>importFile.click()}>{t('导入 JSON','Import JSON')}</button><button onclick={()=>exportJson()}>{t('导出全部','Export all')}</button><button onclick={()=>exportJson(selected)} disabled={!selected.length}>{t('导出所选','Export selected')}</button><button onclick={remove} disabled={!selected.length}>{t('删除所选','Delete selected')}</button><input bind:this={importFile} type="file" accept=".json,application/json" hidden onchange={readImport}/></div></div>
<div class="toolbar"><input placeholder={t('按名称筛选','Filter by name')} bind:value={query}/><select bind:value={active}><option value="all">{t('全部状态','All statuses')}</option><option value="true">{t('启用','Active')}</option><option value="false">{t('停用','Inactive')}</option></select><button onclick={()=>{sortKey='name';asc=!asc}}>{t('名称排序','Sort name')} {asc?'↑':'↓'}</button><button onclick={reset}>{t('恢复工厂默认值','Reset to factory defaults')}</button></div>
<div class="toolbar"><label>{t('批量启用','Bulk active')} <select bind:value={bulkActive}><option value="">—</option><option value="true">{t('启用','Active')}</option><option value="false">{t('停用','Inactive')}</option></select></label><label>{t('迟到分钟','Late min')} <input type="number" min="1" bind:value={bulkLate} placeholder={t('保持不变','Keep')}/></label><label>{t('返回分钟','Return min')} <input type="number" min="1" bind:value={bulkReturn} placeholder={t('保持不变','Keep')}/></label><button disabled={!selected.length} onclick={bulkEdit}>{t('应用批量编辑','Apply bulk edit')}</button></div>
<div class="table-wrap"><table><thead><tr><th></th>{#each [['name','Name','名称'],['description','Description','描述'],['includedSubgroups','Subgroups','小组'],['lateAfterMinutes','Late (min)','迟到(分)'],['returnWindowMinutes','Return (min)','返回(分)'],['active','Active','启用']] as [key,en,zh]}<th><button class="sort" onclick={()=>{sortKey=key;asc=!asc}}>{t(zh,en)} {sortKey===key?(asc?'↑':'↓'):''}</button></th>{/each}<th></th></tr></thead><tbody>{#each visible as p}<tr><td><input type="checkbox" checked={selected.includes(p.id)} onchange={e=>selected=e.currentTarget.checked?[...selected,p.id]:selected.filter(x=>x!==p.id)}/></td><td title={p.name}><b>{p.name}</b>{#if p.id==='default-all'} <span class="chip">{t('默认','Default')}</span>{/if}</td><td>{p.description||'—'}</td><td>{(p.includedSubgroups||[]).join(', ')||'—'}</td><td>{p.lateAfterMinutes}</td><td>{p.returnWindowMinutes}</td><td>{p.active?t('是','Yes'):t('否','No')}</td><td><button onclick={()=>start(p)}>{t('编辑','Edit')}</button></td></tr>{:else}<tr><td colspan="8" class="empty">{t('没有配置','No profiles')}</td></tr>{/each}</tbody></table></div>
<details class="wildcard-help"><summary>{t('通配符帮助','Wildcard help')}</summary><p>{t('仅支持 * 匹配任意字符。问号、方括号、大括号和 ** 不支持。留空小组表示不限制。','Only * is supported and matches any characters. ?, square brackets, braces, and ** are invalid. Empty subgroup list means no restriction.')}</p></details>
</section>
<ConfirmDialog />
{#if open}<div class="overlay"><section class="slide-panel"><button class="close" onclick={()=>open=false}>×</button><h2>{editing?t('编辑考勤配置','Edit profile'):t('新增考勤配置','Add profile')}</h2><label>{t('名称（必填）','Name (required)')}<input bind:value={draft.name} disabled={editing?.id==='default-all'}/></label><label>{t('描述','Description')}<textarea bind:value={draft.description}></textarea></label><label>{t('纳入小组（逗号或换行；* 通配符）','Included subgroups (comma or newline; * wildcard)')}<textarea bind:value={draft.includedSubgroups}></textarea></label><label>{t('迟到阈值（分钟，正整数）','Late threshold (minutes, positive integer)')}<input type="number" min="1" bind:value={draft.lateAfterMinutes}/></label><label>{t('返回窗口（分钟，正整数）','Return window (minutes, positive integer)')}<input type="number" min="1" bind:value={draft.returnWindowMinutes}/></label><label>{t('会议 ID（精确匹配，逗号或换行）','Meeting IDs (exact, comma or newline)')}<textarea bind:value={draft.meetingIds}></textarea></label><label>{t('主题关键词（逗号分隔）','Topic keywords (comma separated)')}<textarea bind:value={draft.topicKeywords}></textarea></label><label>{t('小组排序（每行一个，可用 *）','Group sort order (one per line, * allowed)')}<textarea bind:value={draft.groupSortOrder}></textarea></label><label class="check"><input type="checkbox" bind:checked={draft.active}/>{t('启用','Active')}</label>{#if error}<p class="error">{error}</p>{/if}<div class="actions"><button class="primary" onclick={save}>{t('保存','Save')}</button><button onclick={()=>open=false}>{t('取消','Cancel')}</button></div></section></div>{/if}
{#if preview}<div class="overlay"><section class="slide-panel import-panel"><h2>{t('配置导入预览','Profile import preview')}</h2><div class="toolbar"><label>{t('批量启用','Bulk active')} <select bind:value={bulkActive}><option value="">—</option><option value="true">{t('启用','Active')}</option><option value="false">{t('停用','Inactive')}</option></select></label><label>{t('迟到分钟','Late min')} <input type="number" min="1" bind:value={bulkLate} placeholder={t('保持不变','Keep')}/></label><label>{t('返回分钟','Return min')} <input type="number" min="1" bind:value={bulkReturn} placeholder={t('保持不变','Keep')}/></label><button disabled={!selected.length} onclick={bulkEdit}>{t('应用批量编辑','Apply bulk edit')}</button></div>
<div class="table-wrap"><table><thead><tr><th>{t('行','Row')}</th><th>{t('配置','Profile')}</th><th>{t('操作','Action')}</th><th>{t('原因','Reason')}</th></tr></thead><tbody>{#each preview.changes||[] as c}<tr><td>{c.row}</td><td>{c.id}</td><td>{c.action}</td><td>{c.reason||''}</td></tr>{/each}</tbody></table></div>{#if error}<p class="error">{error}</p>{/if}<div class="actions"><button class="primary" onclick={commit}>{t('确认导入','Confirm import')}</button><button onclick={()=>preview=null}>{t('取消','Cancel')}</button></div></section></div>{/if}
<style>.profile-workspace{padding:20px}.actions{display:flex;gap:7px;align-items:center;flex-wrap:wrap}.wildcard-help{margin-top:14px;color:#596273;font-size:12px}.profile-workspace input:not([type=checkbox]),.profile-workspace select{padding:8px;border:1px solid #dce0e7;border-radius:6px}.profile-workspace .toolbar{flex-wrap:wrap}.slide-panel textarea{min-height:56px}</style>

